<?php require_once __DIR__.'/../includes/header.php';checkAuth(['admin']);$db=getDBConnection();$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)$_POST['id'];$cap=max(1,(int)$_POST['capacidad']);$nombre=trim($_POST['nombre']);$act=(int)isset($_POST['activa']);$s=$db->prepare('UPDATE mesas SET nombre=?,capacidad=?,activa=? WHERE id=?');$s->execute([$nombre,$cap,$act,$id]);$msg='Mesa actualizada.';}$mesas=$db->query('SELECT * FROM mesas ORDER BY numero')->fetchAll();?><div class="card"><h1>Mesas principales</h1><p class="muted">La cantidad principal se controla desde Configuración. Aquí puedes ajustar capacidad y nombre.</p><?php if($msg):?><div class="notice"><?=h($msg)?></div><?php endif;?><div class="grid grid-3"><?php foreach($mesas as $m):?><form method="post" class="card"><input type="hidden" name="id" value="<?=$m['id']?>"><h2>Mesa <?=$m['numero']?></h2><label>Nombre</label><input name="nombre" value="<?=h($m['nombre'])?>"><label>Capacidad</label><input type="number" min="1" name="capacidad" value="<?=$m['capacidad']?>"><label><input type="checkbox" name="activa" <?=$m['activa']?'checked':''?>> Activa</label><button class="btn olive">Guardar</button></form><?php endforeach;?></div></div><?php require_once __DIR__.'/../includes/footer.php';?>
